<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserGroupMembership\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\ValueObject\UserGroupMembershipRelyingPartyVO;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\RelyingPartyRef;

trait UserGroupMembershipRelyingPartyAccessor
{
    private ?UserGroupMembershipRelyingPartyVO $_relyingParty = null;
    public function getRelyingParty(): ?RelyingPartyRef
    {
        return $this->_relyingParty?->value();
    }
    public function relyingParty(): ?UserGroupMembershipRelyingPartyVO
    {
        return $this->_relyingParty;
    }
    public function isRelyingPartyChanged(?self $original = null): bool
    {
        return null !== $this->_relyingParty && !$this->_relyingParty->equals($original?->_relyingParty);
    }
    public function withRelyingParty(UserGroupMembershipRelyingPartyVO|RelyingPartyRef|null $relyingParty): self
    {
        $copy = clone $this;
        $copy->_relyingParty = UserGroupMembershipRelyingPartyVO::from($relyingParty);
        return $copy;
    }
}
